/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ActivatedRouteSnapshot, convertToParamMap, RouterStateSnapshot } from '@angular/router';
import { AppStateService } from '@shared/context/state/app-state.service';
import { urlContextGuard } from './url-context.guard';

describe('urlContextGuard', () => {
  const language = signal('es');
  const tenant = signal('main');

  beforeEach(() => {
    language.set('es');
    tenant.set('main');
    TestBed.configureTestingModule({
      providers: [{ provide: AppStateService, useValue: { language, tenant } }],
    });
  });

  function run(params: Record<string, string>) {
    const route = { paramMap: convertToParamMap(params) } as ActivatedRouteSnapshot;
    return TestBed.runInInjectionContext(() => urlContextGuard(route, {} as RouterStateSnapshot));
  }

  it('aplica el idioma y el tenant de la URL y deja pasar', () => {
    expect(run({ language: 'en-EN', tenant: 'other' })).toBe(true);
    expect(language()).toBe('en-EN');
    expect(tenant()).toBe('other');
  });

  it('no toca el estado si la URL no trae los parámetros', () => {
    expect(run({})).toBe(true);
    expect(language()).toBe('es');
    expect(tenant()).toBe('main');
  });
});
